-- Fictional demo profiles for the public search front. Idempotent. No identity rows.
-- Hide later, before real profiles are published:
--   update public.sp_candidates set publication='unpublished' where source='demo' and fictional=true;
-- Remove later, only the rows this file inserted:
--   delete from public.sp_candidates where source='demo' and fictional=true;
-- The admin screen does the same hide in one step.

do $$
declare r record;
begin
 for r in select conname from pg_constraint where conrelid='public.sp_candidates'::regclass and contype='c' and pg_get_constraintdef(oid) like '%recruitcrm%'
 loop
  execute format('alter table public.sp_candidates drop constraint %I', r.conname);
 end loop;
end $$;
alter table public.sp_candidates add constraint sp_candidates_source_check check (source in ('recruitcrm','talent_network','consented','demo'));

on conflict (id) do nothing;
